.menus {
  display: flex;
  align-items: center;
  width: 10000%;
  cursor pointer;
  padding-left: 12px;
  padding: 9px 0;
  &.on{
	  padding-bottom: 14px;
  }

  .title{
	  color: #333;
	  font-size: 12px;
	  margin-top: 4px;
	  height: 20px;
	  border-radius: 20px;
	  padding: 0 5px;
	  line-height: 20px;
	  text-align: center
  }

  .item {
    position: relative;
    color: #333;
	font-size: 14px;
	margin-right: 28px;
	z-index: 9;

	&.pic{
		margin-right: 15px;
	}

	.pictrue{
		width: 46px;
		height: 46px;
		border: 1px solid #EEEEEE;
		border-radius: 50%;
		background: #f3f9ff;
		margin: 0 auto;
		.img {
			width: 43px;
			height: 43px;
			border-radius: 50%;
		}
		img {
			width: 27px;
		}
	}

	&.on{
		font-size: 16px;
		font-weight: 600;

		span {
		  display: block;
		  position: absolute;
		  left: 50%;
		  bottom: 4px;
		  width: 100%;
		  height: 4px;
		  border-radius: 100px;
		  transform: translateX(-50%);
		  background: #fff;
		  background: linear-gradient(90deg, #E93323 0%, #FF7931 100%);
		  z-index: -1;
		}
	}

	&.on2{
		height: 24px;
		text-align: center;
		line-height: 24px;
		color: #fff;
		background: linear-gradient(90deg, #E93323 0%, #FF7931 100%);
		border-radius: 50px;
		padding: 0 6px;
	}

	&.on3{
		font-size: 16px;
		font-weight: 600;
		color: #E93323;

		span{
			position: absolute;
			width: 30px;
			height: 30px;
			border:3px solid #E93323
			border-left: 3px solid transparent !important;
			border-top: 3px solid transparent !important;
			border-right: 3px solid transparent !important;
			border-radius: 50%
			bottom: -4px;
			left: 50%;
			transform: translateX(-50%);
		}
	}
  }
}
.home_product{
	overflow: hidden;
	.hd_nav{
		display flex
		height 65px
		overflow: hidden;
		padding: 10px 0;
		.item{
			display flex
			flex-direction column
			justify-content center
			margin-right: 37px
			.title{
				font-size 15px
				color #282828
				width 65px
				text-align center
			}
			.label{
				width:56px;
				height:19px;
				line-height 19px
				text-align center
				background:transparent;
				border-radius:10px;
				color #999999
				font-size 11px
			}
			&.active{
				.title{
					color #FF4444
				}
				.label{
					color #fff
					background:linear-gradient(270deg,rgba(255,84,0,1) 0%,rgba(255,0,0,1) 100%);
				}
			}
		}
	}
	.list-wrapper{
		display flex
		flex-wrap wrap
		justify-content space-between
		.item{
			width: 48.5%
			margin-bottom: 10px
			position: relative;
			.jia{
				width: 22px;
				height: 22px;
				background-color: #E93323;
				border-radius: 50%;
				position: absolute;
				right: 10px;
				bottom: 8px;
				.jiaCon{
					width: 100%;
					height: 100%;
					text-align: center;
					line-height: 22px;
					.iconfont{
						color: #fff;
						font-size: 13px;
					}
				}
			}
			.img-box{
				width: 100%
				height: 173px
				.img{
					width: 100%;
					height: 100%;
				}
				img,.box{
					width: 65px
					height: 50px
				}
				.empty-box{
					background:  #F3F9FF
				}
				.box{
					background #D8D8D8
				}
				.label{
					position absolute
					left 0
					top 0
					width:46px;
					height:22px;
					border-radius:10px 0px 10px 0px;
					color #fff
					font-size 13px
					text-align center
					line-height 22px
				}
			}
			.info{
				padding 7px 10px
				background #fff
				border-radius: 0px 0px 10px 10px;
				.pictrue{
					width: 99px;
					height: 14px;
					margin-top: 4px;
					img {
						width: 100%;
						height: 100%;
					}
				}
				.title{
					font-size 14px
					color #282828
				}
				.sales{
					color: #999;
					font-size: 11px;
				}
				.price{
					display flex
					align-items center
					margin-top: 6px;
					img {
						width: 70px;
						height: 15px;
					}
					.num{
						font-size 20px
						margin-right: 4px
						font-family: SemiBold;

						span{
							font-size 12px
						}
					}
					.label{
						width:16px;
						height:18px;
						margin-left 5px
						text-align center
						line-height 18px
						font-size 11px
						&.on{
							margin-left 0;
						}
					}
				}
			}
		}
	}
}
